import pandas as pd
import json

file_url = query['file_url']
operation = query['operation']
columns = query.get('columns', [])
agg = query.get('agg', 'mean')

if str(file_url).lower().endswith('.xlsx') or str(file_url).lower().endswith('.xls'):
    df = pd.read_excel(file_url)
else:
    df = pd.read_csv(file_url)

ALLOWED = {'value_counts', 'groupby_agg', 'correlation', 'missing_report'}
if operation not in ALLOWED:
    return json.dumps({'error': f'operation must be one of {sorted(ALLOWED)}'})

if operation == 'value_counts':
    col = columns[0]
    out = df[col].value_counts(dropna=False).head(50).to_dict()
    result = {str(k): int(v) for k, v in out.items()}

elif operation == 'groupby_agg':
    group_cols = columns[:-1]
    metric_col = columns[-1]
    grouped = df.groupby(group_cols)[metric_col].agg(agg).reset_index()
    result = json.loads(grouped.to_json(orient='records'))

elif operation == 'correlation':
    subset = df[columns] if columns else df.select_dtypes(include='number')
    result = json.loads(subset.corr(numeric_only=True).round(4).to_json())

elif operation == 'missing_report':
    result = {
        'total_rows': int(df.shape[0]),
        'duplicate_rows': int(df.duplicated().sum()),
        'null_counts': {c: int(df[c].isna().sum()) for c in df.columns}
    }

return json.dumps(result)

import requests

