project_name = query['project_name']
query_text = query['query_text']

emb = requests.post('http://ollama:11434/api/embeddings', json={
    'model': 'nomic-embed-text',
    'prompt': query_text
}).json()['embedding']

search = requests.post('http://qdrant:6333/collections/freelance_project_insights/points/search', json={
    'vector': emb,
    'limit': 5,
    'filter': {
        'must': [
            {'key': 'client_id', 'match': {'value': client_id}},
            {'key': 'project_name', 'match': {'value': project_name}}
        ]
    },
    'with_payload': True
}).json()

import json
hits = [r['payload'] for r in search.get('result', [])]
return json.dumps(hits)

import requests, uuid, time

client_id = query['client_id']
project_name = query['project_name']
stage = query['stage']
insight_text = query['insight_text']

emb = requests.post('http://ollama:11434/api/embeddings', json={
    'model': 'nomic-embed-text',
    'prompt': insight_text
}).json()['embedding']

point = {
    'points': [{
        'id': str(uuid.uuid4()),
        'vector': emb,
        'payload': {
            'client_id': client_id,
            'project_name': project_name,
            'stage': stage,
            'insight_text': insight_text,
            'saved_at': int(time.time())
        }
    }]
}

resp = requests.put('http://qdrant:6333/collections/freelance_project_insights/points', json=point)
return resp.text
